def generate_transfermarkt_files():
    df_players = pd.DataFrame(players_data)
    df_squads = pd.DataFrame(squads_data)
    df_mv = pd.DataFrame(market_values_data)
    df_pw = pd.DataFrame(pathways_data)

    df_players.to_csv(os.path.join(RAW_TM_DIR, "transfermarkt_players.csv"), index=False, encoding="utf-8")
    df_squads.to_csv(os.path.join(RAW_TM_DIR, "transfermarkt_squads.csv"), index=False, encoding="utf-8")
    df_mv.to_csv(os.path.join(RAW_TM_DIR, "transfermarkt_market_values.csv"), index=False, encoding="utf-8")
    df_pw.to_csv(os.path.join(RAW_TM_DIR, "transfermarkt_pathways.csv"), index=False, encoding="utf-8")

    print(f"Generated {len(df_players)} players in {RAW_TM_DIR}/transfermarkt_players.csv")
    print(f"Generated {len(df_squads)} squads rows in {RAW_TM_DIR}/transfermarkt_squads.csv")
    print(f"Generated {len(df_mv)} market value records in {RAW_TM_DIR}/transfermarkt_market_values.csv")
    print(f"Generated {len(df_pw)} player pathways in {RAW_TM_DIR}/transfermarkt_pathways.csv")


if __name__ == "__main__":
    generate_transfermarkt_files()
